#### Phase 2: Infrastructure Provisioning

**Step 2.1: Deploy Broker Cluster with Terraform**

```hcl
# terraform/msk-cluster.tf

resource "aws_msk_cluster" "event_cluster" {
  cluster_name           = "production-event-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 6

  broker_node_group_info {
    instance_type = "kafka.m5.4xlarge"
    client_subnets = [
      aws_subnet.private_a.id,
      aws_subnet.private_b.id,
      aws_subnet.private_c.id,
    ]

    storage_info {
      ebs_storage_info {
        volume_size            = 2000
        provisioned_throughput {
          enabled           = true
          volume_throughput = 1000
        }
      }
    }

    connectivity_info {
      public_access {
        type = "DISABLED"
      }
    }

    security_groups = [aws_security_group.msk_brokers.id]
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_encryption.arn
  }

  configuration_info {
    arn      = aws_msk_configuration.event_cluster_config.arn
    revision = aws_msk_configuration.event_cluster_config.latest_revision
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }

  tags = {
    Environment = "production"
    Service     = "event-platform"
    CostCenter  = "infrastructure"
  }
}

resource "aws_msk_configuration" "event_cluster_config" {
  name              = "production-event-config"
  kafka_versions    = ["2.8.1"]
  server_properties = <<PROPERTIES
num.network.threads=16
num.io.threads=16
socket.send.buffer.bytes=1048576
socket.receive.buffer.bytes=1048576
socket.request.max.bytes=104857600

default.replication.factor=3
min.insync.replicas=2
replica.lag.time.max.ms=30000

log.retention.hours=168
log.segment.bytes=1073741824

compression.type=lz4
num.replica.fetchers=8
PROPERTIES
}
```

**Step 2.2: Create Topics and Increase Partitions**

```bash
#!/bin/bash
# scripts/create-topics.sh

BOOTSTRAP_SERVERS="b-1.production.kafka.us-east-1.amazonaws.com:9092"

# High-volume topic: 64 partitions
kafka-topics.sh --create \

  --bootstrap-server $BOOTSTRAP_SERVERS \
  --topic claim-adjudication-events \
  --partitions 64 \
  --replication-factor 3 \
  --config retention.ms=604800000 \
  --config compression.type=lz4 \
  --config min.insync.replicas=2

# Increase partitions on existing topic
kafka-topics.sh --alter \

  --bootstrap-server $BOOTSTRAP_SERVERS \
  --topic existing-topic \
  --partitions 64

kubectl rollout restart deployment/claim-processor -n event-processing
```

