#### Phase 4: Monitoring and Observability

**Step 4.1: Configure CloudWatch Alarms**

```hcl
# terraform/cloudwatch-alarms.tf

resource "aws_cloudwatch_metric_alarm" "high_consumer_lag" {
  alarm_name          = "kafka-high-consumer-lag"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "SumOffsetLag"
  namespace           = "AWS/Kafka"
  period              = 300
  statistic           = "Average"
  threshold           = 1000000
  alarm_description   = "Consumer lag exceeds 1M messages"
  alarm_actions       = [aws_sns_topic.ops_alerts.arn]

  dimensions = {
    "Cluster Name"    = aws_msk_cluster.event_cluster.cluster_name
    "Consumer Group"  = "claim-processors"
    "Topic"           = "claim-adjudication-events"
  }
}

resource "aws_cloudwatch_metric_alarm" "broker_cpu_high" {
  alarm_name          = "kafka-broker-cpu-saturation"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 3
  metric_name         = "CpuUser"
  namespace           = "AWS/Kafka"
  period              = 300
  statistic           = "Average"
  threshold           = 85
  alarm_description   = "Broker CPU sustained above 85%"
  alarm_actions       = [aws_sns_topic.ops_alerts.arn]

  dimensions = {
    "Cluster Name" = aws_msk_cluster.event_cluster.cluster_name
  }
}
```

**Step 4.2: Deploy Monitoring Dashboards**

```yaml
# kubernetes/grafana-dashboard-config.yaml

apiVersion: v1
kind: ConfigMap
metadata:
  name: kafka-dashboards
  namespace: monitoring
data:
  kafka-throughput.json: |
    {
      "panels": [
        {
          "title": "Messages In Per Sec",
          "targets": [{
            "expr": "sum(rate(kafka_server_brokertopicmetrics_messagesin_total[5m]))"
          }]
        },
        {
          "title": "Consumer Lag by Topic",
          "targets": [{
            "expr": "sum by (topic) (kafka_consumer_lag_messages)"
          }]
        },
        {
          "title": "Broker CPU %",
          "targets": [{
            "expr": "avg(kafka_broker_cpu_percent)"
          }]
        }
      ]
    }
```
